"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[365],{4618:e=>{e.exports=JSON.parse('{"functions":[{"name":"cancel","desc":"Removes this task from the schedule permanently. The Handle becomes invalid\\nimmediately and cannot be paused, resumed, or cancelled again.","params":[{"name":"self","desc":"","lua_type":"HandleInternal"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"Handle is already cancelled\\"","desc":"Thrown if called on an already-cancelled Handle."},{"lua_type":"\\"Parent scope is destroyed\\"","desc":"Thrown if the parent Scope was destroyed."}],"source":{"line":167,"path":"src/Chrono.luau"}},{"name":"pause","desc":"Pauses execution of this individual task. The task will not fire while paused,\\nregardless of the parent Scope\'s own pause state.\\n\\nCalling `pause()` on an already-paused Handle is a no-op.","params":[{"name":"self","desc":"","lua_type":"HandleInternal"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"Handle is cancelled\\"","desc":"Thrown if the Handle is invalid."},{"lua_type":"\\"Parent scope is destroyed\\"","desc":"Thrown if the parent Scope was destroyed."}],"source":{"line":189,"path":"src/Chrono.luau"}},{"name":"resume","desc":"Resumes execution of this task after `handle:pause()`. If the parent Scope is\\nalso paused, the task will not fire until the Scope is resumed as well.","params":[{"name":"self","desc":"","lua_type":"HandleInternal"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"Handle is cancelled\\"","desc":"Thrown if the Handle is invalid."},{"lua_type":"\\"Parent scope is destroyed\\"","desc":"Thrown if the parent Scope was destroyed."}],"source":{"line":203,"path":"src/Chrono.luau"}},{"name":"setInterval","desc":"Changes the execution interval for `every` or `tick` tasks. The accumulated\\ntime resets, so the next execution happens `interval` seconds from this call.\\n\\n:::caution\\nOnly valid for Handles created with `scope:every()` or `scope:tick()`. Calling\\nthis on an `after` or `frame` Handle throws an error.\\n:::","params":[{"name":"self","desc":"","lua_type":"HandleInternal"},{"name":"interval","desc":"New interval in seconds.","lua_type":"number"}],"returns":[],"function_type":"static","errors":[{"lua_type":"\\"setInterval is only valid for \'every\' and \'tick\' handles\\"","desc":"Thrown for incompatible handle types."},{"lua_type":"\\"Handle is cancelled\\"","desc":"Thrown if the Handle is invalid."},{"lua_type":"\\"Parent scope is destroyed\\"","desc":"Thrown if the parent Scope was destroyed."}],"source":{"line":224,"path":"src/Chrono.luau"}},{"name":"isPaused","desc":"Returns whether this individual task is paused. Does **not** account for the\\nparent Scope\'s pause state \u2014 only reflects whether `handle:pause()` was called.","params":[{"name":"self","desc":"","lua_type":"HandleInternal"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":242,"path":"src/Chrono.luau"}},{"name":"isCancelled","desc":"Returns whether this task has been cancelled.","params":[{"name":"self","desc":"","lua_type":"HandleInternal"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","errors":[{"lua_type":"\\"Parent scope is destroyed\\"","desc":"Thrown if the parent Scope was destroyed."}],"source":{"line":254,"path":"src/Chrono.luau"}}],"properties":[],"types":[],"name":"Handle","desc":"A reference to a single scheduled task, returned by Scope scheduling methods.\\n\\nUse a Handle to cancel, pause, resume, or reconfigure a task after scheduling.\\nA Handle becomes invalid when `:cancel()` is called or when the parent Scope\\nis destroyed. Calling any method on an invalid Handle throws an error.\\n\\n```lua\\nlocal handle = scope:every(5, function()\\n\\tprint(\\"tick\\")\\nend)\\n\\nhandle:pause()\\nhandle:setInterval(10)\\nhandle:resume()\\nhandle:cancel()\\n```","source":{"line":146,"path":"src/Chrono.luau"}}')}}]);